const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var hongKong = ee.Geometry.Polygon([
    [113.8, 22.1],
    [114.5, 22.1], 
    [114.5, 22.6],
    [113.8, 22.6],
    [113.8, 22.1]
  ]);

  var janPeriod = ['2020-01-01', '2020-01-20'];
  var febPeriod = ['2020-02-10', '2020-02-25'];

  // 2. Data Acquisition - Sentinel-5P NO2
  var no2Collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select('tropospheric_NO2_column_number_density');

  var janCollection = no2Collection.filterDate(janPeriod[0], janPeriod[1]).filterBounds(hongKong);
  var febCollection = no2Collection.filterDate(febPeriod[0], febPeriod[1]).filterBounds(hongKong);

  var janSize = janCollection.size().getInfo();
  var febSize = febCollection.size().getInfo();

  console.log(`Jan 2020 Images: ${janSize}, Feb 2020 Images: ${febSize}`);

  // Check for empty collections
  if (janSize === 0 || febSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean NO2 for each period
  var janMean = janCollection.mean();
  var febMean = febCollection.mean();

  // Check valid pixels
  var janCount = janMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: hongKong,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  var febCount = febMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: hongKong,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  console.log(`Jan Valid Pixels: ${janCount}, Feb Valid Pixels: ${febCount}`);

  if (janCount === 0 || febCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean NO2 values
  var janNo2 = janMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: hongKong,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  var febNo2 = febMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: hongKong,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  console.log(`Jan Mean NO2: ${janNo2 ? janNo2.toFixed(6) : 'N/A'}`);
  console.log(`Feb Mean NO2: ${febNo2 ? febNo2.toFixed(6) : 'N/A'}`);

  // 5. Validation & Final Answer
  if (janNo2 === null || febNo2 === null || isNaN(janNo2) || isNaN(febNo2)) {
    console.log("<answer>C3</answer>");
  } else if (febNo2 < janNo2) {
    console.log(`Decrease: ${((janNo2 - febNo2) / janNo2 * 100).toFixed(1)}%`);
    console.log("<answer>A</answer>");
  } else {
    console.log(`Change: ${((febNo2 - janNo2) / janNo2 * 100).toFixed(1)}%`);
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
